package com.nexus.service; import com.nexus.domain.*; import com.nexus.domain.Rules.*; import com.nexus.web.Views; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.time.*;
@Service @Transactional public class Infrastructure{private final IncidentService svc;private final Clock clock;public Infrastructure(IncidentService s,Clock c){svc=s;clock=c;}public Map<String,Object> graph(){var all=svc.services().findAll();Map<Long,Set<Long>> graph=new HashMap<>(),reverse=new HashMap<>();List<Map<String,Object>> edges=new ArrayList<>();for(ITService s:all)for(Long p:s.providers){graph.computeIfAbsent(p,k->new HashSet<>()).add(s.id);reverse.computeIfAbsent(s.id,k->new HashSet<>()).add(p);edges.add(Views.map("source",p,"target",s.id));}List<Incident> active=svc.incidents().findAll().stream().filter(i->i.status().active()).toList();Set<Long> recent=new HashSet<>();for(Incident i:active)if(i.createdAt.isAfter(clock.instant().minus(Duration.ofHours(24))))recent.add(i.service.id);List<Map<String,Object>> nodes=new ArrayList<>(),suspects=new ArrayList<>();for(ITService s:all){long count=active.stream().filter(i->s.id.equals(i.service.id)).count();Set<Long> down=Rules.reachable(graph,s.id),up=Rules.reachable(reverse,s.id);Set<Long> coverage=new HashSet<>(down);coverage.add(s.id);coverage.retainAll(recent);if(coverage.size()>=2)suspects.add(Views.map("id",s.id,"name",s.name,"coverage",coverage.size(),"affected",coverage,"directEvidence",recent.contains(s.id)));nodes.add(Views.map("id",s.id,"name",s.name,"criticality",s.criticality,"active",count,"state",count>0?"INCIDENT_REPORTED":"NO_ACTIVE_REPORTS","downstream",down,"upstream",up));}suspects.sort(Comparator.comparingInt(x->-(int)x.get("coverage")));return Views.map("nodes",nodes,"edges",edges,"suspects",suspects,"label","Incident-derived service state; not live telemetry");}}
